def run(args):
    p = subprocess.run([sys.executable, RELAY] + args,
                       capture_output=True)
    if p.returncode != 0:
        return p.returncode, None
    return 0, json.loads(p.stdout.decode("utf-8"))

def rand_topo(rng, nodes, allow_down=False, metrics=True):
    names = [chr(0x41 + i) for i in range(nodes)]
    links = []
    pairs = []
    for a in names:
        for b in names:
            if a != b and rng.random() < 0.35:
                pairs.append((a, b))
    # ensure some connectivity: guarantee a ring both directions
    for i in range(nodes):
        pairs.append((names[i], names[(i + 1) % nodes]))
    pairs = sorted(set(pairs))
    for a, b in pairs:
        l = {"from": a, "to": b, "cost": rng.randint(1, 8),
             "up": (True if not allow_down else rng.random() < 0.8)}
        l["bandwidth"] = rng.randint(1, 5)
        l["latency"] = rng.randint(0, 4)
        links.append(l)
    return {"nodes": names, "links": links}, names, pairs

def cmp_packets_netfail(qf, nf):
    # qf: [id,class,status,path,finish,delay,dropLink,hops,reroutes,dropObject]
    # nf: [id,status,path,finish,delay,dropObject,hops,reroutes]
    if len(qf) != len(nf):
        return "len %d vs %d" % (len(qf), len(nf))
    for a, b in zip(qf, nf):
        ida, cls, sa, pa, fa, da, dlink, ha, rr, dobj = a
        idb, sb, pb, fb, db_, dobjb, hb, rrb = b
        if [ida, sa, pa, fa, da] != [idb, sb, pb, fb, db_]:
            return "base mismatch %r vs %r" % (a, b)
        if ha != hb:
            return "hops mismatch %r vs %r" % (ha, hb)
        if rr != rrb:
            return "reroutes mismatch %r vs %r" % (rr, rrb)
        if dobj != dobjb:
            return "dropObject mismatch %r vs %r" % (dobj, dobjb)
        if sa == "overflow":
            if dlink != dobj:
                return "dropLink/dropObject overflow mismatch"
        elif dlink is not None:
            return "dropLink should be null: %r" % (a,)
    return None

def cmp_links_netfail(qf, nf):
    if len(qf) != len(nf):
        return "link len"
    for a, b in zip(qf, nf):
        fa, ta, ea, oa, pa2, la, classes, fra, upa = a
        fb, tb, eb, ob, pb2, lb, frb, upb = b
        if [fa, ta, ea, oa, pa2, la] != [fb, tb, eb, ob, pb2, lb]:
            return "link base %r vs %r" % (a, b)
        if [fra, upa] != [frb, upb]:
            return "link tail %r vs %r" % (a, b)
        if len(classes) != 1:
            return "class rows"
        cn, ce, co, cp, cs = classes[0]
        if [ce, co, cp] != [ea, oa, pa2] or cs != ea:
            return "class counters diverge %r enq=%d ovf=%d peak=%d" % (
                classes, ea, oa, pa2)
    return None

def fuzz_vs_netfail(seed):
    rng = random.Random(seed)
