            rng.choice(names), rng.choice(names))
        pid = "p%d" % k
        data.append([pid, t, s, d, rng.randint(1, 20), "c"])
    ev = []
    et = 0
    for _ in range(rng.randint(1, 10)):
        et += rng.randint(0, 8)
        if rng.random() < 0.5:
            ev.append([et, 0, rng.choice(names), rng.random() < 0.5])
        else:
            a, b = rng.choice(pairs)
            ev.append([et, 1, a, b, rng.random() < 0.5])
    with open("/tmp/qf/f_topo.json", "w") as f:
        json.dump(topo, f)
    ctext = json.dumps(config)
    etext = json.dumps(ev)
    dtext = json.dumps(data)
    queues = [[a, b, caps[(a, b)]] for a, b in pairs]
    dtext5 = json.dumps([row[:5] for row in data])
    c1, r1 = run(["/tmp/qf/f_topo.json", json.dumps(queues), etext,
