    c2, r2 = run(["/tmp/qf/f_topo.json", ctext, etext,
                  dtext])  # qdiscfail: FILE CONFIG EVENTS DATA
    if c1 != c2:
        return "exit codes %d vs %d" % (c1, c2)
    if c1 != 0:
        return None
    if r1["events"] != r2["events"]:
        return "events mismatch\n%r\nvs\n%r" % (r1["events"],
                                               r2["events"])
    err = cmp_packets_netfail(r2["packets"], r1["packets"])
    if err:
        return "packets: " + err + "\nDATA=" + dtext + "\nEV=" + etext \
            + "\nQ=" + json.dumps(queues)
    err = cmp_links_netfail(r2["links"], r1["links"])
    if err:
        return "links: " + err
    return None

def cmp_packets_netqdisc(qf, nq):
    # qf appends reroutes, dropObject; nq row is the first 8 fields.
    if len(qf) != len(nq):
        return "len"
    for a, b in zip(qf, nq):
        if a[:8] != b:
            return "base mismatch\n%r\nvs\n%r" % (a[:8], b)
        if a[8] != 0 or a[9] is not None:
            return "reroutes/dropObject not null: %r" % (a,)
    return None

def cmp_links_netqdisc(qf, nq):
    if len(qf) != len(nq):
        return "len"
    for a, b in zip(qf, nq):
        if a[:7] != b:
            return "base mismatch\n%r\nvs\n%r" % (a[:7], b)
        if a[7] != 0 or a[8] is not True:
            return "tail: %r" % (a,)
    return None

def fuzz_vs_netqdisc(seed):
    rng = random.Random(seed)
    V = rng.randint(2, 6)
    topo, names, pairs = rand_topo(rng, V, allow_down=False)
    C = rng.randint(1, 4)
    classes = []
    for ci in range(C):
        classes.append(["cl%d" % ci, rng.randint(1, 20),
                        rng.randint(1, 40)])
    caps = {(a, b): rng.randint(1, 40) for a, b in pairs}
    config = {"classes": classes,
              "links": [[a, b, caps[(a, b)]] for a, b in pairs]}
    P = rng.randint(0, 12)
    data = []
    t = 0
    for k in range(P):
        t += rng.randint(0, 6)
        s = rng.choice(names)
        d = s if rng.random() < 0.1 else rng.choice(names)
        data.append([
            "p%d" % k, t, s, d, rng.randint(1, 20),
            "cl%d" % rng.randrange(C)])
    # non-empty, strictly no-op events (nodes/links all start up)
    ev = [[0, 0, rng.choice(names), True],
          [5, 1, pairs[0][0], pairs[0][1], True]]
    with open("/tmp/qf/q_topo.json", "w") as f:
        json.dump(topo, f)
    ctext = json.dumps(config)
    dtext = json.dumps(data)
    etext = json.dumps(ev)
    c1, r1 = run(["/tmp/qf/q_topo.json", ctext, dtext])  # netqdisc
    c2, r2 = run(["/tmp/qf/q_topo.json", ctext, etext,
                  dtext])  # qdiscfail
    if c1 != c2:
        return "exit %d vs %d" % (c1, c2)
    if c1 != 0:
        return None
    err = cmp_packets_netqdisc(r2["packets"], r1["packets"])
    if err:
        return "packets: " + err + "\nDATA=" + dtext
    err = cmp_links_netqdisc(r2["links"], r1["links"])
    if err:
        return "links: " + err
    return None

if __name__ == "__main__":
